			localStorage.setItem("keating_ui_settings", JSON.stringify({ alternativeResponseChance: 2 }));
			expect(loadKeatingUiSettings().alternativeResponseChance).toBe(1);
			localStorage.setItem("keating_ui_settings", JSON.stringify({ alternativeResponseChance: -1 }));
			expect(loadKeatingUiSettings().alternativeResponseChance).toBe(0);
		});

		it("migrates the old automatic alternative-response default to one percent", () => {
			localStorage.setItem("keating_ui_settings", JSON.stringify({ alternativeResponseChance: 0.05 }));
			expect(loadKeatingUiSettings().alternativeResponseChance).toBe(0.01);
		});

		it("preserves an explicitly enabled alternative-response chance", () => {
			localStorage.setItem("keating_ui_settings", JSON.stringify({ schemaVersion: 3, alternativeResponseChance: 0.05 }));
			expect(loadKeatingUiSettings().alternativeResponseChance).toBe(0.05);
		});

		it("normalizes the animation renderer to Hyperframes", () => {
			localStorage.setItem("keating_ui_settings", JSON.stringify({ animationRenderer: "hyperframes" }));
			const settings = loadKeatingUiSettings();
			expect(settings.animationRenderer).toBe("hyperframes");
		});
}

type LegacyUiSettingsInput = Partial<KeatingUiSettings>
	& Partial<Record<LegacyGroundingKey, "auto" | "off">>
	& { schemaVersion?: number };

function normalizeSettings(value: LegacyUiSettingsInput | null): KeatingUiSettings {
	const webSearch =
		value?.webSearch === "off" || (value?.webSearch === undefined && value?.[LEGACY_GOOGLE_GROUNDING_KEY] === "off")
			? "off"
			: DEFAULT_UI_SETTINGS.webSearch;

	return {
		showToolUi: value?.showToolUi ?? DEFAULT_UI_SETTINGS.showToolUi,
		autoOpenArtifacts: value?.autoOpenArtifacts ?? DEFAULT_UI_SETTINGS.autoOpenArtifacts,
		showRawErrors: value?.showRawErrors ?? DEFAULT_UI_SETTINGS.showRawErrors,
		reasoningLevel: value?.reasoningLevel ?? DEFAULT_UI_SETTINGS.reasoningLevel,
		animationRenderer: "hyperframes",
		fontFamily:
			value?.fontFamily === "space-mono" || value?.fontFamily === "roboto" || value?.fontFamily === "jetbrains-mono"
				? value.fontFamily
				: DEFAULT_UI_SETTINGS.fontFamily,
		shareLinkMode: normalizeShareLinkMode(value?.shareLinkMode),
		shareWarningAcknowledged: value?.shareWarningAcknowledged === true,
		// Older builds shipped either 5% or 0% as automatic defaults. Version 3
		// makes comparisons deliberately rare at 1%, while preserving every other
		// explicitly chosen probability.
		alternativeResponseChance:
			value?.schemaVersion !== UI_SETTINGS_SCHEMA_VERSION
				&& (value?.alternativeResponseChance === 0.05 || value?.alternativeResponseChance === 0)
				? DEFAULT_UI_SETTINGS.alternativeResponseChance
				: normalizeAlternativeResponseChance(value?.alternativeResponseChance),
		userProfileImage: typeof value?.userProfileImage === "string" && value.userProfileImage.startsWith("data:image/") ? value.userProfileImage : DEFAULT_UI_SETTINGS.userProfileImage,
		imageGenerator: isImageGeneratorId(value?.imageGenerator) ? value.imageGenerator : DEFAULT_UI_SETTINGS.imageGenerator,
		imageModel: typeof value?.imageModel === "string" ? value.imageModel : DEFAULT_UI_SETTINGS.imageModel,
		imageSize: typeof value?.imageSize === "string" ? value.imageSize : DEFAULT_UI_SETTINGS.imageSize,
		imageQuality: typeof value?.imageQuality === "string" ? value.imageQuality : DEFAULT_UI_SETTINGS.imageQuality,
		localImageBaseUrl: typeof value?.localImageBaseUrl === "string" ? value.localImageBaseUrl : DEFAULT_UI_SETTINGS.localImageBaseUrl,
		webSearch,
		flashcardSoundEnabled: value?.flashcardSoundEnabled === true,
	};

